#ifndef LINK_UDP_POLICY_H
#define LINK_UDP_POLICY_H
#include <stdint.h>
#include <stddef.h>
#include <string.h>
/* Scoped policy for the three private packet formats generated by the mod.
 * trusted_member must come from kernel ingress-interface evidence AND a live
 * mod-owned bound sender tuple, never from packet bytes or source IP alone.
 * Returns 1 to reject. Other protocol formats need a separate audit; this
 * function is deliberately not a complete PRO DJ LINK parser/firewall.
 */
static int probe_udp_private_number(unsigned n) { return n==7 || n==8; }
static int probe_udp_private_ip(const uint8_t *ip) {
    return ip[0]==127 && ip[1]==77 && ip[2]==0 && probe_udp_private_number(ip[3]);
}
static int probe_udp_reject(const uint8_t *p,size_t size,unsigned port,unsigned trusted_member) {
    int trusted=probe_udp_private_number(trusted_member);
    if (!p || size<11 || memcmp(p,"Qspt1WmJOL",10)) return trusted;
    if (port==50000 && p[10]==6) {
        if (size<54) return 1;
        int private_claim=probe_udp_private_number(p[0x24]) || probe_udp_private_ip(p+0x2c);
        if (trusted) return size!=54 || p[0x24]!=trusted_member ||
            !probe_udp_private_ip(p+0x2c) || p[0x2f]!=trusted_member;
        return private_claim;
    }
    if (port==50002 && p[10]==10) {
        if (size<0x25) return 1;
        if (trusted) return size!=1152 || p[0x21]!=trusted_member || p[0x24]!=trusted_member;
        return probe_udp_private_number(p[0x21]) || probe_udp_private_number(p[0x24]);
    }
    if (port==50002 && p[10]==6) {
        if (size<0x2c) return 1;
        unsigned owner=((unsigned)p[0x24]<<24)|((unsigned)p[0x25]<<16)|((unsigned)p[0x26]<<8)|p[0x27];
        if (trusted) return size!=192 || p[0x21]!=trusted_member || owner!=trusted_member;
        return probe_udp_private_number(p[0x21]) || probe_udp_private_number(owner);
    }
    /* Owned synthetic transports emit only the three formats above. */
    return trusted;
}
#endif
